-- Verified native-code spans, read from PBZ.exe before any input or native-state access.
-- Only relative code/data addresses changed between these two builds; latch remains at 0x4c6.
local profiles = {
    [511072344] = {build="26266538", spans={
        {98340640,""},
        {98341008,"40534883ec2080b9c304000000488bd9c6815a05000000c681c6040000000f85d300000080b9c4040000"},
        {98338688,"80b95a05000000488b81b00400000fb69041020000741afeca80fa017739488d915c050000488b89a0040000e97fb9fcff80b9c604000000741d80fa01740580fa027513488d916c050000488b89a0040000e959b9fcffc3cccccccccccccccc48897424"},
        {98340528,"40534883ec20488bd9488b89b00400004881c128010000488b01ff90e000000084c07437488b8ba0040000488d936c050000e8b994fcff84c07427488b8ba0040000488d935c050000e832b2fcffc683c6040000004883c4205bc3c6835a05000001c683c604000000"},
    }},
    [498913272] = {build="26367565", spans={
        {98639376,""},
        {98639744,"40534883ec2080b9c304000000488bd9c6815a05000000c681c6040000000f85d300000080b9c4040000"},
        {98637424,"80b95a05000000488b81b00400000fb69041020000741afeca80fa017739488d915c050000488b89a0040000e95fb5fcff80b9c604000000741d80fa01740580fa027513488d916c050000488b89a0040000e939b5fcffc3cccccccccccccccc48897424"},
        {98639264,"40534883ec20488bd9488b89b00400004881c128010000488b01ff90e000000084c07437488b8ba0040000488d936c050000e89990fcff84c07427488b8ba0040000488d935c050000e812aefcffc683c6040000004883c4205bc3c6835a05000001c683c604000000"},
    }},
}
local M = {}
function M.verify(filename)
    local file = assert(io.open(filename, "rb"), "PBZ.exe is unavailable")
    local ok, result = pcall(function()
        local profile = assert(profiles[file:seek("end")], "Unsupported game executable; no native state access permitted")
        for _, span in ipairs(profile.spans) do
            assert(file:seek("set", span[1]) == span[1], "Native code seek failed")
            local expected = span[2]:gsub("..", function(h) return string.char(tonumber(h, 16)) end)
            assert(file:read(#expected) == expected, "Native sprint layout differs; no input changes permitted")
        end
        return profile.build
    end)
    file:close()
    assert(ok, result)
    return result
end
-- The caller has already verified the original adapter's hash. Its gameplay logic
-- stays in that local dependency; only its executable validator is supplied here.
function M.adapter(original)
    assert(type(original) == "table" and type(original.new) == "function"
        and type(original.verify) == "function", "Unexpected sprint adapter interface")
    original.verify = M.verify
    return original
end
return M
